from typing import Set, List
import random


def load_dictionary() -> Set[str]:
    dictionary = set(["HELLO", "WORLD", "HOUSE", "TABLE", "CHAIR"])
    return dictionary


def is_valid_word(word: str) -> bool:
    dictionary = load_dictionary()
    if len(word) != 5:
        return False
    if not word.isalpha():
        return False
    return word.upper() in dictionary


def get_random_word() -> str:
    dictionary = list(load_dictionary())
    random_word = random.choice(dictionary)
    return random_word


def normalize_word(word: str) -> str:
    normalized_word = word.strip().upper()
    return normalized_word
